class Solution {
public:
    string reverseWords(string s) {
        reverse(s.begin(), s.end());
        int n = s.size();
        int writeIdx = 0;
        int i = 0;
        while (i < n) {
            while (i < n && s[i] == ' ') i++;
            if (i >= n) break;
            int start = i;
            while (i < n && s[i] != ' ') i++;
            reverse(s.begin() + start, s.begin() + i);
            if (writeIdx > 0) s[writeIdx++] = ' ';
            for (int j = start; j < i; j++) {
                s[writeIdx++] = s[j];
            }
        }
        s.resize(writeIdx);
        return s;
    }
};
